<script setup lang="ts">import {Headset,Send,MessageSquareText} from 'lucide-vue-next'
const subject=ref('');const message=ref('');const busy=ref(false);const result=ref('')
async function send(){result.value='';busy.value=true;try{await $fetch('/api/feedback',{method:'POST',body:{subject:subject.value,message:message.value}});result.value='Đã ghi nhận phản hồi vào PostgreSQL (mô phỏng).';subject.value='';message.value=''}catch(e){result.value=readableError(e)}finally{busy.value=false}}
</script>
<template><div class="space-y-4"><div><h2 class="text-xl font-black">Liên hệ và phản hồi</h2><p class="text-sm text-muted">Gửi góp ý và yêu cầu hỗ trợ sử dụng kênh Công dân.</p></div><div class="grid gap-4 md:grid-cols-2"><section class="panel space-y-3 p-5"><h3 class="section-label"><Headset :size="20" class="text-blue-600"/>Kênh hỗ trợ</h3><p class="text-sm leading-7 text-slate-600">Bạn có thể gửi phản hồi trực tuyến, xem hướng dẫn sử dụng hoặc đặt câu hỏi về hồ sơ trong trang chi tiết hồ sơ.</p><NuxtLink to="/huong-dan" class="btn-outline">Xem hướng dẫn</NuxtLink></section><form class="panel space-y-4 p-5" @submit.prevent="send"><h3 class="section-label"><MessageSquareText :size="20" class="text-brand-600"/>Gửi phản hồi</h3><div><label class="field-label">Chủ đề</label><input v-model="subject" class="field" required minlength="3" maxlength="150" placeholder="Ví dụ: Góp ý giao diện tra cứu"/></div><div><label class="field-label">Nội dung</label><textarea v-model="message" class="field" rows="5" required minlength="10" maxlength="3000" placeholder="Mô tả nội dung cần hỗ trợ..."/></div><p v-if="result" class="rounded-lg bg-blue-50 p-3 text-sm text-brand-800">{{result}}</p><button class="btn-primary" :disabled="busy||message.trim().length<10" type="submit"><Send :size="17"/> Gửi phản hồi</button></form></div></div></template>
